app.get('/api/credentials', async (req, res) => {
  if (!brokerEnabled()) return res.json({ enabled: false });
  try {
    try { await syncPluginSlots(); } catch { /* status below still answers */ }
    const info = await brokerInfo();
    const who = resolveIdentity(req);
    // Which slot each catalog model spends from: the pickers' "your key / no key" badges.
    const models = {};
    try {
      for (const m of await listModels()) {
        const r = modelSlot(m.id);
        if (r) models[m.id] = r.slot ? { slot: r.slot } : r.keyless ? { keyless: true } : { error: r.error };
      }
    } catch { /* badges are a nicety: an unreadable catalog leaves them off */ }
    // "Push as me" (docs/credential-broker.md): the card shows the person's GitHub only when worca uses it.
    const base = { enabled: true, mode: info.mode, keyPage: info.publicUrl || null, models, githubAsPerson: asPersonMode(process.env) };
    if (info.mode !== 'multi') return res.json({ ...base, person: null, slots: (await personSlots('local')).slots });
    if (!isSharedIdentity(who.source)) return res.json({ ...base, person: null, slots: [] });
    const r = await personSlots(who.name);
    res.json({ ...base, person: r.person, slots: r.slots });
  } catch (err) {
    res.status(502).json({ enabled: true, error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/settings', async (req, res) => {
  const person = awayPersonOf(req);   // B4: a signed-in person sees their own Away switch
  res.json({ ...settingsState(), ...(person ? { nightModeToggle: nightModeToggleFor(person), nightModePerPerson: person } : {}), ...(await autoModelState()), ...(await prDescriptionModelState()), ...(await agentGenModelState()), ...(await namingModelState()), ...(await commandSummaryModelState()), ...(await requirementsInterviewState()), chat: chatPrefs(), app: APP_INFO });
});

app.post('/api/settings', async (req, res) => {
  const body = req.body || {};
  const has = (k) => Object.prototype.hasOwnProperty.call(body, k);
  // D4: actions.editor / actions.terminal are command paths the built-ins route spawns as the server user.
  // runLimits.keepRunsDays archives (deletes the files of) old runs: an agent never sets it either.
  if ((has('actions') || has('runLimits')) && agentMayBeCaller(req)) return refuseAgentCaller(res);
  // Hosted with browsing limited: the Worca root and projects root move only within Worca's own
  // folders (both widen what can be browsed, and the setters probe the path). Clearing is fine.
  if (!(await requireFsAllowed(req, res, [has('root') ? normalizeProjectPath(body.root) : null,
    has('projectsRoot') ? normalizeProjectPath(body.projectsRoot) : null]))) return;
  try {
    const { actionsWarnings } = await applySettingsPatch(body, { person: awayPersonOf(req) });
    res.json({ ...settingsState(), ...(await autoModelState()), ...(await prDescriptionModelState()), ...(await agentGenModelState()), ...(await namingModelState()), ...(await commandSummaryModelState()), ...(await requirementsInterviewState()), chat: chatPrefs(),
      ...(actionsWarnings ? { actionsWarnings } : {}) });
  } catch (err) {
    // 400 with the user's words and, when known, the body path of the bad field (#555).
    const { error, field } = settingsErrorReply(err, err && err.settingsCtx);
    return res.status(400).json({ error, ...(field ? { field } : {}) });
  }
});
